  var ids=S.edit&&S.edit.kind==="hero"&&S.edit.r===r?S.edit.ids:((P.hero&&P.hero.ids&&P.hero.ids.length)?P.hero.ids.slice():all.filter(function(p){return p.img}).map(function(p){return p.id}));
