function crmSubscribe(){
  if(isTechRole()){sub(db.collection("jobs").where("assignedEmail","==",myEm()),"jobs");sub(db.collection("techPay").where("tech","==",myEm()),"tpay");return true}
  if(can("finance")){sub(db.collection("expenses").orderBy("date","desc").limit(5000),"exp");sub(db.collection("recurring"),"rec");sub(db.collection("personal").orderBy("date","desc").limit(3000),"pers");sub(db.collection("rates"),"rates");sub(db.collection("techPay").orderBy("date","desc").limit(5000),"tpay");
    S.unsub.push(db.collection("finance").doc("settings").onSnapshot(function(s){S.finS=s.exists?s.data():{};refresh()},function(){}));
    S.unsub.push(db.collection("finance").doc("company").onSnapshot(function(s){S.co=s.exists?s.data():{};refresh()},function(){}))}
  return false}
