/* ---------- money fixes: tax, customer payments, receivables, sales tax ---------- */
function isUnpaid(j){return j.status==="done"&&num(j.amount)>0&&j.payStatus!=="paid"&&!(j.payStatus==null&&(j.date||"")<"2026-11-01")}
function jobsOwing(){return S.jobs.filter(function(j){return isUnpaid(j)&&inRegion(j)}).sort(function(a,b){return (a.date||"").localeCompare(b.date||"")})}
function taxCollected(a,b){return S.jobs.filter(function(j){return j.status==="done"&&inR(j.date,a,b)}).reduce(function(s,j){return s+regAmt({region:j.region,amount:num(j.tax)})},0)}
function taxPaid(a,b){return S.exp.filter(function(x){return inR(x.date,a,b)}).reduce(function(s,x){return s+regAmt({region:x.region||"both",amount:num(x.tax)})},0)}
var finOver0=finOver;
finOver=function(){var h=finOver0(),R=prange(S.fp),ow=jobsOwing(),owT=ow.reduce(function(s,j){return s+num(j.amount)+num(j.tax)},0),tc=taxCollected(R.a,R.b),tp=taxPaid(R.a,R.b);
  var extra='<div class="two"><div class="card"><h3>Customers who still owe you <small>'+money(owT)+'</small></h3>'+(ow.length?'<div class="tblw"><table class="tbl rsp"><tbody>'+ow.slice(0,12).map(function(j){var d=Math.round((Date.now()-new Date(j.date+"T12:00:00"))/864e5);return '<tr><td data-l="Job"><b>'+esc(cname(j.customer))+'</b><br><small>'+nice(j.date)+' · '+d+' day'+(d===1?"":"s")+' ago'+(j.payStatus==="deposit"?" · deposit paid":"")+'</small></td><td data-l="Owing" style="text-align:right">'+money(num(j.amount)+num(j.tax))+'</td><td><button class="btn ok sm" data-act="jpaid" data-id="'+esc(j._id)+'">Paid</button></td></tr>'}).join("")+'</tbody></table></div>'+(ow.length>12?'<p class="mut tiny">+'+(ow.length-12)+' more — see Jobs.</p>':''):'<div class="emp">Every finished job is paid 👍</div>')+'<p class="mut tiny" style="margin:10px 0 0">Mark a job paid here, or set “Payment” in the job.</p></div>'+
   '<div class="card"><h3>Sales tax (HST / GST) <small>'+R.label+'</small></h3><dl class="odl"><dt>Charged to customers</dt><dd>'+money(tc)+'</dd><dt>Paid on expenses (input tax credits)</dt><dd>− '+money(tp)+'</dd><dt class="tot">Estimated to send to CRA</dt><dd class="tot">'+money(tc-tp)+'</dd></dl>'+
   '<p class="mut tiny" style="margin:10px 0 0">Only counts tax you entered on jobs and expenses. Revenue and expenses on this page are before tax. Saskatchewan PST isn\'t claimable — ask your accountant before filing.</p></div></div>';
  var i=h.lastIndexOf('<div class="two"><div class="card"><h3>Where the money goes');return i>-1?h.slice(0,i)+extra+h.slice(i):h+extra};

