  var t=ymd(),tech=isTechRole(),jobs=(tech?jobsMine():S.jobs).filter(function(j){return j.date===t&&j.status!=="cancelled"}).sort(function(a,b){return (a.time||"").localeCompare(b.time||"")}),R=todayRems(myEm()),C2=S.cmps.filter(function(c){return ["open","assigned","in-progress"].indexOf(c.status)>-1&&(!tech||c.assignedEmail===myEm())}),F=tech?[]:(can("work")?follow():[]);
  if(!jobs.length&&!R.length&&!C2.length&&!F.length)return;var h=new Date().getHours(),hi=h<12?"Good morning":h<17?"Good afternoon":"Good evening";
